SourceCode.Declaration:
/// <summary>
/// Request used to stage, activate, inspect, execute, and roll back an interpreted module.
/// A dependency may be expressed as Name (pin the active version) or Name@Version.
/// </summary>
[DataContract]
public final class MXTXppInterpreterModuleRequest
{
    str moduleName;
    str sourceCode;
    List dependencies = new List(Types::String);
    int version;
    boolean activate;
    str requestId;
}

Method.Source:
[DataMember("ModuleName")]
public str parmModuleName(str _moduleName = moduleName)
{
    moduleName = _moduleName;
    return moduleName;
}

[DataMember("SourceCode")]
public str parmSourceCode(str _sourceCode = sourceCode)
{
    sourceCode = _sourceCode;
    return sourceCode;
}

[DataMember("Dependencies"),
 DataCollection(Types::String)]
public List parmDependencies(List _dependencies = dependencies)
{
    dependencies = _dependencies;
    return dependencies;
}

[DataMember("Version")]
public int parmVersion(int _version = version)
{
    version = _version;
    return version;
}

[DataMember("Activate")]
public boolean parmActivate(boolean _activate = activate)
{
    activate = _activate;
    return activate;
}

[DataMember("RequestId")]
public str parmRequestId(str _requestId = requestId)
{
    requestId = _requestId;
    return requestId;
}
